module DronePlacement(\n    input [3:0] n,\n    input [3:0] k,\n    input [63:0] adj,\n    output reg possible\n);\n    integer node_i, node_j, s_i;\n    reg valid_sub, is_indep;\n    reg [7:0] max_size;\n    integer count_i;\n\n    always @(*) begin\n        max_size = 0;\n        \n        for (s_i = 0; s_i < 256; s_i = s_i + 1) begin\n            valid_sub = 1;\n            is_indep = 1;\n            count_i = 0;\n\n            // Validate subset nodes\n            for (node_i = 0; node_i < 8; node_i = node_i + 1) begin\n                if (s_i[node_i] && node_i >= n) valid_sub = 0;\n            end\n            \n            if (valid_sub) begin\n                // Check independence\n                for (node_i = 0; node_i < 8; node_i = node_i + 1) begin\n                    if (s_i[node_i]) begin\n                        count_i = count_i + 1;\n                        for (node_j = node_i + 1; node_j < 8; node_j = node_j + 1) begin\n                            // Adj matrix indexing is [i*8 + j]\n                            if (s_i[node_j] && adj[(node_i << 3) + node_j]) is_indep = 0;\n                        end\n                    end\n                end\n                \n                // Update max_size\n                if (is_indep && (count_i > max_size)) max_size = count_i;\n            end\n        end\n        \n        possible = (max_size >= k);\n    end\nendmodule